import{_ as t}from"./chunks/emo.CGwrrK0y.js";import{_ as o}from"./chunks/emergency-button-gui.DfAcsUhG.js";import{_ as r,o as s,c as a,a5 as n}from"./chunks/framework.CcrBcQWS.js";const y=JSON.parse('{"title":"Emergency Stop Procedures","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/emergency-stop-procedures.md","filePath":"manual/safety/emergency-stop-procedures.md","lastUpdated":1787021357000}'),i={name:"manual/safety/emergency-stop-procedures.md"};function l(p,e,c,d,g,m){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="emergency-stop-procedures" tabindex="-1">Emergency Stop Procedures <a class="header-anchor" href="#emergency-stop-procedures" aria-label="Permalink to &quot;Emergency Stop Procedures&quot;">​</a></h1><p>How to stop the robot immediately in an emergency and how to recover. Routine emergency stop and recovery are also on <a href="/RBQ/nightly/manual/operation/emo.html">Emergency Stop and Recovery</a>.</p><h2 id="automatic-stop-and-safety-related-behavior" tabindex="-1">Automatic stop and safety-related behavior <a class="header-anchor" href="#automatic-stop-and-safety-related-behavior" aria-label="Permalink to &quot;Automatic stop and safety-related behavior&quot;">​</a></h2><p>The robot may stop automatically or cut motor power in the following cases:</p><ul><li><strong>Fall detected</strong></li><li><strong>Low battery</strong></li><li><strong>Controller (app) stop command</strong> received</li><li><strong>Interrupt</strong> signal during an automatic mission</li></ul><p>The RBQ has <strong>emergency stop (E-Stop)</strong>, <strong>remote stop</strong>, <strong>speed limit</strong>, <strong>posture stabilization</strong>, and other safety-related features. On flat ground, assume a <strong>stopping distance of up to about 1 m</strong> for safety-related stops; on slopes or uneven floors it can be longer.</p><h2 id="using-the-emergency-stop-button" tabindex="-1">Using the emergency stop button <a class="header-anchor" href="#using-the-emergency-stop-button" aria-label="Permalink to &quot;Using the emergency stop button&quot;">​</a></h2><figure><img src="'+t+'" alt="Emergency stop push button on rear of robot"><figcaption style="text-align:center;">[ Emergency stop push button on the rear of the robot ]</figcaption></figure><p>Pressing the <strong>emergency stop push button</strong> on the rear puts all joints into <strong>High Damping</strong>. In this state the robot resists external forces but does not accept torque or position commands-control is disabled and the robot may settle to the floor.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>Emergency stop protects people and the robot. Press the button immediately if there is abnormal motion, collision risk, shock, or pinch risk. <strong>It is for real emergencies-not for everyday stopping.</strong> Repeated unnecessary use can add risk by losing controlled stability.</p></div></div><h2 id="recovery-after-emergency-stop" tabindex="-1">Recovery after emergency stop <a class="header-anchor" href="#recovery-after-emergency-stop" aria-label="Permalink to &quot;Recovery after emergency stop&quot;">​</a></h2><ol><li><strong>Release the button</strong>: Turn the emergency stop button clockwise back to its normal position.</li><li><strong>Restore posture</strong>: Press &quot;Stance&quot; in the GUI or set initial posture per <a href="/RBQ/nightly/manual/operation/initial-pose.html">Robot Initial Pose Setting</a>.</li><li><strong>Find the cause</strong>: Remove or fix the cause of the stop (obstacle, error, wrong settings) before operating again.</li></ol><h2 id="stop-from-the-app-gui" tabindex="-1">Stop from the app (GUI) <a class="header-anchor" href="#stop-from-the-app-gui" aria-label="Permalink to &quot;Stop from the app (GUI)&quot;">​</a></h2><figure><img src="'+o+'" alt="Emergency button at top center of RBQ GUI"><figcaption style="text-align:center;">[ Emergency button at top center of RBQ GUI ]</figcaption></figure><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Pressing <strong>Emergency</strong> cuts power to all motors. Use only in critical situations.</p></div></div><h2 id="residual-motion-after-power-off" tabindex="-1">Residual motion after power off <a class="header-anchor" href="#residual-motion-after-power-off" aria-label="Permalink to &quot;Residual motion after power off&quot;">​</a></h2><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>After power is off, RBQ legs <strong>do not auto-lock.</strong> On slopes, stairs, or slippery floors the robot can still slide, roll, or move by inertia-power off does not immediately mean fully safe.</p></div></div><p>On slopes, stairs, or slippery floors after power off you may still get:</p><ul><li><strong>Sliding</strong></li><li><strong>Rolling or falling</strong></li><li><strong>Continued motion from inertia</strong></li></ul><p>Before approaching, check floor condition and posture; approach only from a safe direction.</p>',20)])])}const b=r(i,[["render",l]]);export{y as __pageData,b as default};
